{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver de tre betingelsesled korrekt: almindelige SU-/slutlånsbetingelser, videregående uddannelse eller dansk EUD (inkl. EUX), og varig fysisk/psykisk funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen. Det angiver korrekt, at tillægget udbetales som tillæg til SU-stipendium eller slutlån. Ingen af rubrikkens væsentlige fejl forekommer."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med, herunder at tillægget udbetales sammen med SU-stipendium eller slutlån og at man skal være indskrevet på og gennemgå uddannelsen. EUX er også nævnt."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer direkte spørgsmålet om betingelserne med en punktopstilling af betingelserne uden irrelevant tekst."},
    "c04_source_traceability": {"label": "met", "reason": "Svaret henviser til vejledningens afsnit 3.1–3.3, som er en identificerbar kilde."},
    "c05_source_validity": {"label": "met", "reason": "Vejledningens afsnit 3.1–3.3 findes i de frosne kilder og er autoritative og anvendelige til spørgsmålet."},
    "c06_claim_source_support": {"label": "not_met", "reason": "Afsnit 3.1–3.3 støtter størstedelen af svaret. Den varige funktionsnedsættelse med meget betydelige begrænsninger fremgår af 3.1, men er i øvrigt behandlet i afsnit 3.4, som svaret ikke citerer. Dette er en mindre henvisningsunøjagtighed. Sætningen om, at tillægget udbetales som tillæg til stipendium eller slutlån, støttes af 3.2.1, som ligger uden for det angivne interval 3.1–3.3. Den fulde støtte til alle påstande inden for de citerede afsnit er derfor ikke opfyldt."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Svaret tilføjer ingen væsentlige regler, betingelser eller undtagelser uden støtte i materialet. Indskrevet-på/gennemgå-kravet og EUX står i kilderne."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Rubrikken kræver ingen særskilt standardadvarsel. Svaret bevarer 'varig' og 'meget betydelige begrænsninger'. Den ikke-udtømmende karakter er antydet ved 'herunder'."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er en sammenhængende opremsning af betingelserne, og konklusionen følger af de anførte led uden modsigelser."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Skal' bruges om de kumulative betingelser, hvilket svarer til kilden ('for at få handicaptillæg skal ... opfylde'). Der gøres ingen skønsmæssige elementer absolutte."}
  },
  "xhaile_coverage": {
    "A1": {"label": "yes", "reason": "Svaret nævner kravet om at opfylde de almindelige betingelser for SU eller slutlån."},
    "A2": {"label": "yes", "reason": "Svaret nævner, at man skal gå på en videregående uddannelse eller dansk EUD, herunder EUX."},
    "A3": {"label": "yes", "reason": "Svaret nævner varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde."},
    "A4": {"label": "yes", "reason": "Svaret nævner at have ret til SU og være indskrevet på og gennemgå en SU-berettigende uddannelse."},
    "A6": {"label": "partial", "reason": "EUD inklusive EUX er nævnt, men svaret nævner ikke, at erhvervslignende uddannelser i udlandet ikke er omfattet."}
  },
  "overall_notes": "Juridisk korrekt og fuldstændigt overblik over de tre betingelsesled. Eneste svaghed er kildeunderstøttelsen: Udbetalingen som tillæg til stipendium/slutlån hviler på 3.2.1, og funktionsnedsættelsen uddybes i 3.4, men svaret citerer kun 3.1–3.3 samlet. Derfor not_met på C06, selvom det er et grænsetilfælde."
}

